import React from 'react';
import { Alert } from '@mui/material';
import { Visibility as ViewIcon } from '@mui/icons-material';

const ReviewerReadOnlyBanner: React.FC = () => (
  <Alert
    severity="info"
    icon={<ViewIcon fontSize="inherit" />}
    sx={{ mb: 3 }}
  >
    You have read-only access. Registry changes, billing controls, and payment details require a
    platform administrator.
  </Alert>
);

export default ReviewerReadOnlyBanner;
